def minEnergy(n: int, brightness: int, intervals: list[list[int]]) -> int:
    if not intervals:
        return 0
    intervals.sort()
    merged = []
    cur_s, cur_e = intervals[0]
    for s, e in intervals[1:]:
        if s <= cur_e:
            cur_e = max(cur_e, e)
        else:
            merged.append((cur_s, cur_e))
            cur_s, cur_e = s, e
    merged.append((cur_s, cur_e))
    total_coverage = sum(e - s + 1 for s, e in merged)
    return total_coverage * brightness

#include <vector>
#include <algorithm>

class Solution {
public:
    long long minEnergy(int n, int brightness, std::vector<std::vector<int>>& intervals) {
        if (intervals.empty()) return 0;
        std::sort(intervals.begin(), intervals.end());
        long long totalCoverage = 0;
        int curS = intervals[0][0], curE = intervals[0][1];
        for (size_t i = 1; i < intervals.size(); ++i) {
            int s = intervals[i][0], e = intervals[i][1];
            if (s <= curE) {
                curE = std::max(curE, e);
            } else {
                totalCoverage += (curE - curS + 1);
                curS = s;
                curE = e;
            }
        }
        totalCoverage += (curE - curS + 1);
        return totalCoverage * brightness;
    }
};

import java.util.*;

class Solution {
    public long minEnergy(int n, int brightness, int[][] intervals) {
        if (intervals.length == 0) return 0;
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
        long totalCoverage = 0;
        int curS = intervals[0][0], curE = intervals[0][1];
        for (int i = 1; i < intervals.length; i++) {
            int s = intervals[i][0], e = intervals[i][1];
            if (s <= curE) {
                curE = Math.max(curE, e);
            } else {
                totalCoverage += (curE - curS + 1);
                curS = s;
                curE = e;
            }
        }
        totalCoverage += (curE - curS + 1);
        return totalCoverage * brightness;
    }
}

function minEnergy(n, brightness, intervals) {
    if (intervals.length === 0) return 0;
    intervals.sort((a, b) => a[0] - b[0]);
    let totalCoverage = 0;
    let curS = intervals[0][0], curE = intervals[0][1];
    for (let i = 1; i < intervals.length; i++) {
        const [s, e] = intervals[i];
        if (s <= curE) {
            curE = Math.max(curE, e);
        } else {
            totalCoverage += (curE - curS + 1);
            curS = s;
            curE = e;
        }
    }
    totalCoverage += (curE - curS + 1);
    return totalCoverage * brightness;
}
